// Synthetic data ONLY; no annotations or reviews are persisted by this fixture.
import {NEG_ORG,prepareNegativeSet,blindNegativeExport,type NegInput} from '../../supabase/functions/_shared/luna-negative-v2';
import {decisionsHash} from '../../supabase/functions/_shared/decisions-config';
export const negId=(n:number)=>'00000000-0000-4000-8000-'+String(n).padStart(12,'0');
export function negInventory(low=8,mixed=12,positive=12){const unused:NegInput[]=[];for(let i=0;i<low+mixed+positive;i++){const bucket=i<low?'low':i<low+mixed?'mixed':'positive',text=bucket==='low'?'The soup was cold and the food was bland.':bucket==='mixed'?'The pizza was delicious but the portions were small.':'The food was delicious and the staff were friendly.';unused.push({review_id:negId(i+1),organization_id:NEG_ORG,establishment_id:negId(100+i%8),establishment_name:'Synthetic restaurant '+i%8,rating:bucket==='low'?1+i%4:5,original_text:text,original_language:'en'});}return {history_tables:['synthetic_history'],historical_review_ids:10,total_text_reviews:100,unused};}
export async function negativeFixture(low=4){const body=await prepareNegativeSet(negInventory(low), '2026-10-13T00:00:00.000Z'),sha=await decisionsHash(body);return {record:{id:negId(900),body,body_sha256:sha,sealed_at:body.created_at},reference_seal:null,blind_export:blindNegativeExport(body),paid_enabled:false as const,new_paid_calls:0 as const};}
